<script setup>
import {computed,onMounted,reactive,ref} from 'vue'
import {dateLabel} from '../../utils'
import {readReviewSentiment} from '../../services/reviewSentiment'
const props=defineProps({kind:String,row:{type:Object,required:true},busy:Boolean,error:String,preview:Boolean,selfId:String})
const emit=defineEmits(['close','save-member','analyze','delete-review','set-sentiment'])
const dialog=ref(null),form=reactive({role:props.row.role,status:props.row.status || '정상',sentiment:props.row.sentiment || '긍정'})
const sentiment=computed(()=>readReviewSentiment(props.row))
const close=()=>{if(!props.busy)dialog.value.close()}
onMounted(()=>dialog.value.showModal())
</script>
<template><dialog ref="dialog" class="admin-record-dialog" :class="kind+'-dialog'" :aria-labelledby="'record-dialog-heading'" @close="emit('close')" @cancel="busy && $event.preventDefault()"><header><div><span>{{ kind==='members' ? '회원 관리' : '리뷰 관리' }}</span><h2 id="record-dialog-heading">{{ kind==='members' ? '회원 상세' : '리뷰 상세' }}</h2></div><button type="button" aria-label="상세 팝업 닫기" :disabled="busy" @click="close">×</button></header>
 <template v-if="kind==='members'"><section class="member-profile"><span class="member-profile-avatar">{{ row.name?.slice(0,1) || '회' }}</span><div><h3>{{ row.name }}</h3><p>{{ row.email || '이메일 미등록' }}</p></div><span class="record-dialog-status" :data-status="row.status">{{ row.status }}</span></section><dl class="member-profile-facts"><div><dt>로그인 ID</dt><dd>{{ row.username || row.userId }}</dd></div><div><dt>회원 번호</dt><dd>{{ row.userId }}</dd></div><div><dt>연락처</dt><dd>{{ row.phone || '미등록' }}</dd></div><div><dt>가입일</dt><dd>{{ row.createdAt ? dateLabel(row.createdAt) : '미등록' }}</dd></div></dl><form id="member-dialog-form" class="member-controls" @submit.prevent="emit('save-member',{role:form.role,status:form.role==='ADMIN' ? row.status : form.status})"><h3>계정 관리</h3><div><label>회원 권한<select v-model="form.role" :disabled="busy || row.userId===selfId"><option value="USER">일반 회원</option><option value="ADMIN">관리자</option></select></label><label>계정 상태<select v-model="form.status" :disabled="busy || form.role==='ADMIN'"><option>정상</option><option>비활성</option><option>강퇴</option></select></label></div><p v-if="row.userId===selfId">현재 로그인한 계정의 권한은 변경할 수 없습니다.</p></form></template>
 <template v-else><section class="review-dialog-product"><img v-if="row.productImage" :src="row.productImage" alt=""><div><span>구매 상품</span><h3>{{ row.productName || row.productId }}</h3></div></section><div class="review-dialog-byline"><strong>{{ row.author }}</strong><span>{{ row.date ? dateLabel(row.date) : '' }}</span><span v-if="sentiment.label" class="record-dialog-status" :data-status="sentiment.label">{{ sentiment.label }}</span></div><blockquote class="review-dialog-body">{{ row.body }}</blockquote><p v-if="sentiment.score!==null" class="review-confidence">감정분석 신뢰도 <strong>{{ (sentiment.score*100).toFixed(1) }}%</strong></p></template>
 <label v-if="preview && kind==='reviews'" class="preview-review-edit">감정 표시 (수동)<select v-model="form.sentiment"><option>긍정</option><option>부정</option></select></label><p v-if="preview" class="record-dialog-note">화면 확인용 데이터입니다. 실제 DB에는 반영되지 않습니다.</p><p v-if="error" class="error" role="alert">{{ error }}</p><footer><button type="button" class="button" :disabled="busy" @click="close">닫기</button><div v-if="kind==='members'"><button form="member-dialog-form" type="submit" class="button gold" :disabled="busy">{{ busy ? '저장 중…' : '변경사항 저장' }}</button></div><div v-else><button v-if="preview" type="button" class="button" :disabled="busy" @click="emit('set-sentiment',form.sentiment)">감정 표시 저장</button><button v-else type="button" class="button" :disabled="busy" @click="emit('analyze')">리뷰 분석</button><button type="button" class="button record-dialog-delete" :disabled="busy" @click="emit('delete-review')">리뷰 삭제</button></div></footer></dialog></template>
<style>
.preview-review-edit{display:flex;align-items:center;gap:12px;font-size:16px;margin:20px 0}.preview-review-edit select{padding:9px 12px;font:inherit;border:1px solid #d6deea;border-radius:7px;background:#fff}

.admin-record-dialog{width:min(740px,calc(100vw - 32px));max-height:90dvh;overflow:auto;border:1px solid #dce3ec;border-radius:18px;background:#fff;color:#26364a;padding:28px;box-shadow:0 24px 90px #14243c30}.admin-record-dialog::backdrop{background:#15213580;backdrop-filter:blur(4px)}.admin-record-dialog>header{display:flex;justify-content:space-between;align-items:center;margin-bottom:24px}.admin-record-dialog>header span{font-size:14px;color:#718096}.admin-record-dialog h2{font-size:27px;margin:5px 0 0}.admin-record-dialog>header>button{border:0;background:transparent;font-size:32px;cursor:pointer;color:inherit}.member-profile{display:flex;align-items:center;gap:18px;background:#f4f7fb;padding:22px;border-radius:12px}.member-profile-avatar{display:grid;place-items:center;flex:none;width:64px;height:64px;border-radius:18px;background:#e2eafa;color:#4967a2;font-size:28px;font-weight:750}.member-profile h3{font-size:25px;margin:0}.member-profile p{font-size:17px;color:#718096;margin:7px 0 0;overflow-wrap:anywhere}.member-profile .record-dialog-status{margin-left:auto}.record-dialog-status{padding:7px 11px;border-radius:6px;background:#edf1f6;color:#52667f;font-size:16px;font-weight:700;white-space:nowrap}.record-dialog-status[data-status='정상'],.record-dialog-status[data-status='긍정']{background:#e6f5ed;color:#19865b}.record-dialog-status[data-status='강퇴'],.record-dialog-status[data-status='부정']{background:#fff0ed;color:#c84845}.member-profile-facts{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:22px 28px;padding:24px 0;margin:0}.member-profile-facts div{min-width:0}.member-profile-facts dt{font-size:15px;color:#718096;margin-bottom:7px}.member-profile-facts dd{margin:0;font-size:18px;font-weight:650;overflow-wrap:anywhere}.member-controls{border-top:1px solid #e3e9f0;padding-top:20px}.member-controls h3{font-size:20px;margin:0 0 16px}.member-controls>div{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.member-controls label{display:grid;gap:9px;font-size:16px;font-weight:650}.member-controls select{height:46px;width:100%;font:inherit;border:1px solid #d6deea;border-radius:7px;padding:8px 10px;background:#fff;color:inherit}.member-controls p,.record-dialog-note{font-size:14px;color:#718096;line-height:1.6}.admin-record-dialog footer{display:flex;justify-content:space-between;gap:12px;border-top:1px solid #e3e9f0;margin-top:24px;padding-top:20px}.admin-record-dialog footer>div{display:flex;gap:10px}.admin-record-dialog .button{min-height:44px;font-size:16px;padding:10px 16px}.record-dialog-delete{color:#be4545!important;border-color:#e6bdbd!important}.review-dialog-product{display:flex;align-items:center;gap:18px;padding:20px;background:#f4f7fb;border-radius:12px}.review-dialog-product img{width:80px;height:80px;object-fit:contain;background:#fff;border-radius:8px}.review-dialog-product span{font-size:14px;color:#718096}.review-dialog-product h3{font-size:21px;line-height:1.5;margin:6px 0 0}.review-dialog-byline{display:flex;align-items:center;gap:12px;margin:24px 0;font-size:16px;color:#718096}.review-dialog-byline strong{color:#26364a;font-size:18px}.review-dialog-byline .record-dialog-status{margin-left:auto}.review-dialog-body{margin:0;padding:22px;border:1px solid #e3e9f0;border-radius:10px;font-size:19px;line-height:1.85;white-space:pre-wrap;overflow-wrap:anywhere;min-height:150px}.review-confidence{font-size:16px;color:#718096}.review-confidence strong{color:#365f9b;margin-left:8px}@media(max-width:600px){.admin-record-dialog{padding:20px}.member-profile{padding:16px;gap:12px;flex-wrap:wrap}.member-profile h3{font-size:23px}.member-profile-avatar{width:50px;height:50px}.member-profile-facts{gap:18px}.member-profile-facts dd{font-size:16px}.member-controls>div{grid-template-columns:1fr}.admin-record-dialog footer{flex-wrap:wrap}.review-dialog-product h3{font-size:18px}}
</style>
